CREATE TABLE ibexa_content_version (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, contentobject_id INTEGER DEFAULT NULL, created INTEGER DEFAULT 0 NOT NULL, creator_id INTEGER DEFAULT 0 NOT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INTEGER DEFAULT 0 NOT NULL, status INTEGER DEFAULT 0 NOT NULL, user_id INTEGER DEFAULT 0 NOT NULL, version INTEGER DEFAULT 0 NOT NULL, workflow_event_pos INTEGER DEFAULT 0);
